   497          {
   498                  const tcphdr* hdr = reinterpret_cast<const tcphdr*>(data);
   499                  return dataLen >= sizeof(tcphdr)
   500                          && hdr->dataOffset >= 5 /* the minimum TCP header size */
   501                          && dataLen >= hdr->dataOffset * sizeof(uint32_t);
